// A four-car train, seen from above, running laps of a circle of track: the start-up screen's (splash.ts, with
// the logo inside it), and, centred on the screen, the one shown while any panel waits for its data (waitingPanel,
// through loading() in dom.ts).
//
// The track is drawn here so that rails, sleepers and clips follow the circle exactly. The cars are in
// web/public/brand/, generated by web/scripts/brand_assets.py. Nothing here comes from dom.ts, which uses it.

const NS = "http://www.w3.org/2000/svg";

// Loop geometry (viewBox units). The code handles a stadium (two straights
// joined by half circles); with HALF = 0 it is a plain circle.
const VW = 400, VH = 400;
const CX = VW / 2, CY = VH / 2;
const HALF = 0;                   // half the length of each straight
const R = 162;                    // radius of the curves, measured on the track centre line
const GAUGE = 8;                  // rails sit this far either side of the centre line
const SLEEPER_LENGTH = 30, SLEEPER_SPACING = 16;
const CAR_LENGTH = 70, CAR_WIDTH = 70 * 44 / 144, CAR_GAP = 1.5;
const CARS = ["train-top-lead", "train-top-car", "train-top-car", "train-top-tail"];     // front to back
const LAP_SECONDS = 4.8;

const loop = (r: number) =>
  `M ${CX - HALF} ${CY - r} L ${CX + HALF} ${CY - r} A ${r} ${r} 0 0 1 ${CX + HALF} ${CY + r} ` +
  `L ${CX - HALF} ${CY + r} A ${r} ${r} 0 0 1 ${CX - HALF} ${CY - r} Z`;
const LENGTH = 4 * HALF + 2 * Math.PI * R;

function el(tag: string, attrs: Record<string, string | number>, ...children: (Element | Element[])[]): SVGElement {
  const node = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, String(v));
  node.append(...children.flat());
  return node;
}

/** Position and heading (degrees) at distance s along the centre line, clockwise from the top-left. */
function pointAt(s: number): { x: number; y: number; angle: number } {
  s = ((s % LENGTH) + LENGTH) % LENGTH;
  const straight = 2 * HALF, arc = Math.PI * R;
  if (s < straight) return { x: CX - HALF + s, y: CY - R, angle: 0 };
  s -= straight;
  if (s < arc) { const t = -Math.PI / 2 + s / R; return { x: CX + HALF + R * Math.cos(t), y: CY + R * Math.sin(t), angle: (t * 180) / Math.PI + 90 }; }
  s -= arc;
  if (s < straight) return { x: CX + HALF - s, y: CY + R, angle: 180 };
  s -= straight;
  const t = Math.PI / 2 + s / R;
  return { x: CX - HALF + R * Math.cos(t), y: CY + R * Math.sin(t), angle: (t * 180) / Math.PI + 90 };
}

function track(): SVGElement {
  const count = Math.round(LENGTH / SLEEPER_SPACING);
  const period = LENGTH / count;                      // a whole number of sleepers, so the loop closes cleanly
  const dash = 0.42 * period;
  const fittings: SVGElement[] = [];
  for (let k = 0; k < count; k++) {                    // base plates and yellow clips beside each rail
    const p = pointAt(k * period + dash / 2);
    fittings.push(el("g", { transform: `translate(${p.x.toFixed(2)} ${p.y.toFixed(2)}) rotate(${p.angle.toFixed(2)})` },
      [-GAUGE, GAUGE].flatMap((y) => [
        el("rect", { x: -3.2, y: y - 3.6, width: 6.4, height: 7.2, rx: 0.8, fill: "#8b8076" }),
        el("path", { d: `M -2.2 ${y - 2.6} h 4.4 M -2.2 ${y + 2.6} h 4.4`, stroke: "#e3b221", "stroke-width": 1.2, "stroke-linecap": "round" }),
      ])));
  }
  const rails = [R - GAUGE, R + GAUGE].flatMap((r) => [
    el("path", { d: loop(r), fill: "none", stroke: "#2f241c", "stroke-width": 4.6, opacity: 0.35, transform: "translate(0 0.8)" }),
    el("path", { d: loop(r), fill: "none", stroke: "#7b4a2d", "stroke-width": 3.4 }),
    el("path", { d: loop(r), fill: "none", stroke: "#d9d3ca", "stroke-width": 1.2 }),
  ]);
  return el("g", {},
    el("path", { d: loop(R), fill: "none", stroke: "#9c978e", "stroke-width": SLEEPER_LENGTH + 1.4, "stroke-dasharray": `${dash} ${period - dash}` }),
    el("path", { d: loop(R), fill: "none", stroke: "#c9c5bd", "stroke-width": SLEEPER_LENGTH, "stroke-dasharray": `${dash} ${period - dash}` }),
    fittings, rails);
}

function train(animate: boolean): SVGElement[] {
  const pitch = CAR_LENGTH + CAR_GAP;
  return CARS.map((name, i) => {
    const image = el("image", { href: `/brand/${name}.svg`, x: -CAR_LENGTH / 2, y: -CAR_WIDTH / 2, width: CAR_LENGTH, height: CAR_WIDTH });
    if (!animate) {                                    // parked across the top
      const p = pointAt(HALF + 1.5 * pitch - i * pitch);
      return el("g", { transform: `translate(${p.x} ${p.y}) rotate(${p.angle})` }, image);
    }
    // Every car runs the same lap; each one behind the lead is a little later on it.
    const ahead = ((CARS.length - 1 - i) * pitch / LENGTH) * LAP_SECONDS;
    return el("g", {}, image,
      el("animateMotion", { dur: `${LAP_SECONDS}s`, repeatCount: "indefinite", rotate: "auto", path: loop(R), begin: `${(-ahead - 0.001).toFixed(3)}s` }));
  });
}

/** The track with its train, sized by ``className`` in styles.css; ``tight`` crops the margin around the track, so a
 * small loop gives the train as much room as it can. The train stands still when the system asks for reduced motion
 * or Settings → Animations is None (that setting's CSS cannot stop an SVG animation). */
export function trainLoop(className: string, tight = false): SVGSVGElement {
  const animate = !window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
    && document.documentElement.getAttribute("data-motion") !== "none";
  const edge = tight ? CX - (R + SLEEPER_LENGTH / 2 + 2) : 0;
  return el("svg", { viewBox: `${edge} ${edge} ${VW - 2 * edge} ${VH - 2 * edge}`, class: className, "aria-hidden": "true" },
    track(), train(animate)) as SVGSVGElement;
}

// --- One train for everything that is loading ---
// Panels waiting at the same time share one train, centred on the content pane (on the whole screen in fullscreen or
// in a dialog), with the caption of the panel that has waited longest. While a dialog or a fullscreen view is open,
// only what waits inside it counts: the page behind it never puts the train over it. Each panel holds an empty
// placeholder where its content will go (a box holding nothing else is not drawn: styles.css); the train leaves when
// the last placeholder on view has been replaced. Placeholders are checked every 100 ms rather than told: the pages
// replace them with clear(), which says nothing.

interface Waiting { el: HTMLElement; caption: string; checks: number }
const waiting: Waiting[] = [];
let overlay: { box: HTMLElement; caption: HTMLElement } | null = null;
let ticker = 0;

/** A placeholder for a panel's content; while it is on view, the train runs centred on the screen. */
export function waitingPanel(caption: string): HTMLElement {
  const placeholder = document.createElement("div");
  placeholder.className = "loading";
  waiting.push({ el: placeholder, caption, checks: 0 });
  if (!ticker) ticker = window.setInterval(check, 100);
  requestAnimationFrame(check);                       // put in place by now: show the train without waiting a tick
  return placeholder;
}

function check(): void {
  for (let i = waiting.length - 1; i >= 0; i--) {
    const w = waiting[i];
    if (w.el.isConnected) w.checks = 1;
    else if (w.checks++ > 0) waiting.splice(i, 1);   // replaced by its content, or never placed
  }
  const top = document.fullscreenElement ?? document.querySelector("dialog[open]:modal");
  const shown = waiting.find((w) => w.el.isConnected && (w.el.checkVisibility?.() ?? true) && (!top || top.contains(w.el)));
  if (!shown) {
    overlay?.box.remove();
    overlay = null;
    if (!waiting.length) { window.clearInterval(ticker); ticker = 0; }
    return;
  }
  if (!overlay) {
    const caption = document.createElement("span");
    const card = document.createElement("div");
    card.className = "screen-loader-card";
    card.append(trainLoop("loading-loop", true), caption);
    const box = document.createElement("div");
    box.className = "screen-loader";
    box.setAttribute("role", "status");
    box.setAttribute("aria-live", "polite");
    box.append(card);
    overlay = { box, caption };
  }
  if (overlay.caption.textContent !== shown.caption) overlay.caption.textContent = shown.caption;
  place(overlay.box, top);
}

// Over the content pane (the sidebar stays clear), cut to what is on screen; in fullscreen or in a dialog, the whole
// screen, inside that element, since nothing outside it is drawn.
function place(box: HTMLElement, top: Element | null): void {
  const host = top ?? document.body;
  if (box.parentElement !== host) host.append(box);
  const pane = top ? null : document.querySelector(".workspace")?.getBoundingClientRect();
  const left = Math.max(0, pane?.left ?? 0), right = Math.min(window.innerWidth, pane?.right ?? window.innerWidth);
  const up = Math.max(0, pane?.top ?? 0), down = Math.min(window.innerHeight, pane?.bottom ?? window.innerHeight);
  Object.assign(box.style, { left: `${left}px`, top: `${up}px`, width: `${Math.max(0, right - left)}px`, height: `${Math.max(0, down - up)}px` });
}
